function haHost(panel) {
  let panels = [], current = null;
  const ws = msg => panel.hass.callWS(msg);
  haWs = ws;
  const status = p => p.auth_failed ? 'mit anderem HA gekoppelt (SW6+SW10 beim Start halten)'
    : p.mode === 'local' ? 'lokal verwaltet' : p.connected ? 'verbunden' : 'offline';
  return {
    hideName: true,
    saveLabel: 'Speichern und an das Panel senden',
    entities(domains) {
      return Object.values(panel.hass.states)
        .filter(s => domains.includes(s.entity_id.split('.')[0]))
        .map(s => [s.entity_id, s.attributes.friendly_name || ''])
        .sort((a, b) => a[0].localeCompare(b[0]));
    },
    async start(ui) {
      panels = await ws({type: 'smartbuttons/panels'});
      if (!panels.length) {
        ui.msg('Noch kein Panel eingerichtet: Einstellungen → Geräte & Dienste → SmartButtons.', 'err');
        return;
      }
      const label = document.createElement('span');
      label.textContent = 'Panel';
      const sel = document.createElement('select');
      const info = document.createElement('span');
      info.className = 'hint';
      panels.forEach((p, i) => {
        const o = document.createElement('option');
        o.value = i;
        o.textContent = p.name;
        sel.append(o);
      });
      const load = async () => {
        current = panels[sel.value];
        info.textContent = [status(current), current.version, current.host].filter(Boolean).join(' · ');
        ui.apply(await ws({type: 'smartbuttons/get_config', entry_id: current.entry_id}));
        if (current.mode === 'local') {
          ui.msg('Das Panel ist lokal verwaltet. Gespeichertes übernimmt es erst, wenn es in seiner Web-UI auf Home Assistant umgestellt ist.', 'err');
        } else {
          ui.msg('');
        }
      };
      sel.onchange = () => load().catch(e => ui.msg('Fehler: ' + e.message, 'err'));
      ui.slot.append(label, sel, info, await passwordRow(ui));
      await load();
    },
    async save(config) {
      const r = await ws({type: 'smartbuttons/set_config', entry_id: current.entry_id, config});
      return r.pushed ? 'Gespeichert, das Panel startet neu.'
                      : 'Gespeichert. Das Panel übernimmt es, sobald es verbunden ist.';
    },
  };
}

// One password for the web UI and OTA of all panels. HA sends it to every panel.
async function passwordRow(ui) {
  const row = document.createElement('div');
  row.className = 'bar';
  row.style.width = '100%';
  const label = document.createElement('span');
  label.textContent = 'Passwort aller Panels (Web-UI und OTA, Benutzer admin)';
  const input = document.createElement('input');
  input.style.width = '220px';
  input.style.fontFamily = 'monospace';
  input.value = (await haWs({type: 'smartbuttons/get_password'})).password;
  const set = document.createElement('button');
  set.textContent = 'Passwort setzen';
  set.onclick = async () => {
    try {
      const r = await haWs({type: 'smartbuttons/set_password', password: input.value});
      ui.msg(`Passwort gesetzt, ${r.panels} verbundene Panels haben es schon.`, 'ok');
    } catch (e) {
      ui.msg('8 bis 32 Zeichen, ohne Leerzeichen und Umlaute.', 'err');
    }
  };
  row.append(label, input, set);
  return row;
}

